<?php declare(strict_types=1); namespace Modules\Settings\Controllers; use App\Http\Controllers\Controller; use App\Services\SettingsService; use Core\Http\RedirectResponse; use Core\Http\Request; use Core\Http\Response; class SettingController extends Controller { public function __construct(private readonly SettingsService $settings) { } public function index(): Response { return $this->view('settings::Admin.index', [ 'title' => trans('common.settings'), 'settings' => $this->settings->all(), ]); } public function update(Request $request): RedirectResponse { $data = $request->validate([ 'company_name' => 'required|string|max:255', 'contact_email' => 'required|email', 'contact_phone' => 'nullable|string|max:50', 'default_meta_description' => 'nullable|string|max:255', ]); $this->settings->setMany($data, auth()->id()); return $this->redirect(route('admin.settings.index')) ->with('_success', trans('common.saved')); } } 